-- Stage 11b (1 of 5): categories mapped to the website's 7 Club Card categories
-- Tom's choices from the review page (https://claude.ai/artifact/DLucB792pjaV87MDs4ufcm), 23 Oct 2026:
-- everything as suggested, except the Formers listed in supabase/.local/11b/choices.txt.
-- Generated by supabase/.local/11b/make_fix.py.
--
-- Sets businesses.category to one of the website's 7 Club Card categories (Food & Drink, Health & Beauty, Retail, Entertainment, Activities, Services, For Children),
-- or to none for colleagues, councils and community groups. 693 businesses change; the rest
-- already hold the right value. A business whose category changed since the review is left alone.
-- Every row it changes is copied to cc_phase0_backup (reason 'stage11b_categories_2026_10_24') first.
-- Undo: supabase/data-fixes/20261024_stage11b_1_categories_undo.sql
-- Run with psql -v ON_ERROR_STOP=1 after migration 20261024_001_stage11b. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage11b_categories_2026_10_24') THEN
    RAISE EXCEPTION 'stage11b_categories_2026_10_24 has already been applied';
  END IF;
END $$;

CREATE TEMP TABLE _cat (biz uuid PRIMARY KEY, biz_name text NOT NULL, old_cat text, new_cat text) ON COMMIT DROP;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM _cat WHERE new_cat IS NOT NULL AND new_cat NOT IN ('Food & Drink', 'Health & Beauty', 'Retail', 'Entertainment', 'Activities', 'Services', 'For Children')) THEN
    RAISE EXCEPTION 'a category outside the seven';
  END IF;
END $$;

-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM _cat m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

-- leave out any business whose category was edited since the review
DELETE FROM _cat m USING businesses b WHERE b.id = m.biz AND b.category IS DISTINCT FROM m.old_cat;

SELECT 'businesses', b.id, to_jsonb(b), 'stage11b_categories_2026_10_24' FROM businesses b WHERE b.id IN (SELECT biz FROM _cat);

UPDATE businesses b SET category = m.new_cat FROM _cat m WHERE b.id = m.biz;

DO $$ DECLARE n int; odd int; BEGIN
  SELECT count(*) INTO n FROM cc_phase0_backup WHERE reason = 'stage11b_categories_2026_10_24';
  SELECT count(*) INTO odd FROM businesses b
  WHERE b.merged_into IS NULL AND b.category IS NOT NULL AND b.category NOT IN ('Food & Drink', 'Health & Beauty', 'Retail', 'Entertainment', 'Activities', 'Services', 'For Children')
    AND b.id IN (SELECT biz FROM _cat);
  IF odd > 0 THEN RAISE EXCEPTION 'check failed: % businesses outside the seven', odd; END IF;
  RAISE NOTICE 'stage 11b categories: % businesses changed (% in the review list)', n, 693;
END $$;

COMMIT;
